/* Starry Background Animation */
.stars, .stars2, .stars3 {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
}

.stars {
  background: transparent url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><circle cx="20" cy="20" r="1" fill="white" opacity="0.8"/><circle cx="80" cy="50" r="0.5" fill="white" opacity="0.6"/><circle cx="50" cy="80" r="1.5" fill="white" opacity="0.4"/><circle cx="10" cy="70" r="0.8" fill="white" opacity="0.7"/><circle cx="90" cy="10" r="1.2" fill="white" opacity="0.5"/></svg>') repeat;
  animation: animateStars 50s linear infinite;
}

.stars2 {
  background: transparent url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><circle cx="30" cy="40" r="1" fill="white" opacity="0.6"/><circle cx="70" cy="70" r="0.8" fill="white" opacity="0.8"/><circle cx="40" cy="10" r="1.2" fill="white" opacity="0.4"/><circle cx="85" cy="85" r="0.6" fill="white" opacity="0.7"/></svg>') repeat;
  animation: animateStars 100s linear infinite;
}

.stars3 {
  background: transparent url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><circle cx="60" cy="30" r="0.5" fill="white" opacity="0.5"/><circle cx="25" cy="60" r="1" fill="white" opacity="0.3"/><circle cx="75" cy="15" r="0.8" fill="white" opacity="0.6"/><circle cx="45" cy="90" r="1.5" fill="white" opacity="0.4"/></svg>') repeat;
  animation: animateStars 150s linear infinite;
}

@keyframes animateStars {
  from {
    transform: translateY(0px);
  }
  to {
    transform: translateY(-100vh);
  }
}

/* Preloader Styles */
.scroll-preloader {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(15, 23, 42, 0.95);
  backdrop-filter: blur(10px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
}

.spinner {
  width: 60px;
  height: 60px;
  border: 3px solid rgba(100, 116, 139, 0.3);
  border-top: 3px solid #64748b;
  border-radius: 50%;
  animation: spin 1s linear infinite;
}

@keyframes spin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

.fade-in-up {
  animation: fadeInUp 0.8s ease-out;
}

@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(30px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.slide-in-left {
  animation: slideInLeft 0.8s ease-out;
}

@keyframes slideInLeft {
  from {
    opacity: 0;
    transform: translateX(-50px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@tailwind base;
@tailwind components;
@tailwind utilities;

/* Custom Scrollbar Styles */
.scrollbar-thin {
  scrollbar-width: thin;
}

.scrollbar-thin::-webkit-scrollbar {
  width: 6px;
