import { useState } from 'react'
import { motion } from 'framer-motion'
import { useCart } from '../hooks/useCart'
import { FiTrash2, FiMinus, FiPlus, FiShoppingBag } from 'react-icons/fi'
import { useNavigate } from 'react-router-dom'
import { toast } from 'react-hot-toast'
import MultiEventPaymentModal from '../components/MultiEventPaymentModal'

export default function CartPage() {
  const { cartItems, removeFromCart, updateQuantity, clearCart } = useCart()
  const navigate = useNavigate()
  const [showPaymentModal, setShowPaymentModal] = useState(false)

  const handleQuantityChange = async (itemId, newQuantity) => {
    if (newQuantity < 1) {
      await removeFromCart(itemId)
    } else {
      await updateQuantity(itemId, newQuantity)
    }
    // Force a small delay to ensure the UI updates are complete
    setTimeout(() => {
      window.dispatchEvent(new CustomEvent('cartUpdated'))
    }, 100)
  }

  const handleRemoveItem = async (itemId) => {
    await removeFromCart(itemId)
    // Force a small delay to ensure the UI updates are complete
    setTimeout(() => {
      window.dispatchEvent(new CustomEvent('cartUpdated'))
    }, 100)
  }

  const handleClearCart = async () => {
    await clearCart()
    // Force a small delay to ensure the UI updates are complete
    setTimeout(() => {
      window.dispatchEvent(new CustomEvent('cartUpdated'))
    }, 100)
  }

  const calculateTotal = () => {
    return cartItems?.reduce((total, item) => {
      return total + (item.ticketType.price * item.quantity)
    }, 0) || 0
  }

  const handleCheckout = () => {
    if (!cartItems || cartItems.length === 0) {
      toast.error('Your cart is empty')
      return
    }

    // Show payment modal for checkout
    setShowPaymentModal(true)
  }

  return (
    <div className="min-h-screen bg-slate-900 text-white">
      {/* Header */}
      <div className="bg-slate-800 border-b border-slate-700">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-4">
              <button
                onClick={() => navigate('/')}
                className="text-slate-400 hover:text-white transition-colors"
              >
                ← Back to Events
              </button>
              <h1 className="text-2xl font-bold">Shopping Cart</h1>
            </div>
            <div className="flex items-center space-x-2">
              <FiShoppingBag className="w-6 h-6" />
              <span className="text-lg font-semibold">
                {cartItems?.length || 0} items
              </span>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {!cartItems || cartItems.length === 0 ? (
          /* Empty Cart */
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="text-center py-16"
          >
            <FiShoppingBag className="w-24 h-24 mx-auto text-slate-600 mb-6" />
            <h2 className="text-2xl font-bold text-slate-300 mb-4">Your cart is empty</h2>
            <p className="text-slate-400 mb-8">
              Looks like you haven't added any tickets to your cart yet.
            </p>
            <button
              onClick={() => navigate('/')}
              className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-3 rounded-lg font-semibold transition-colors"
            >
              Browse Events
            </button>
          </motion.div>
        ) : (
          /* Cart Items */
          <div className="grid lg:grid-cols-3 gap-8">
            {/* Cart Items List */}
            <div className="lg:col-span-2 space-y-4">
              <div className="flex items-center justify-between mb-6">
                <h2 className="text-xl font-bold">Cart Items</h2>
                <button
                  onClick={handleClearCart}
                  className="text-red-400 hover:text-red-300 transition-colors flex items-center space-x-2"
                >
                  <FiTrash2 className="w-4 h-4" />
                  <span>Clear Cart</span>
                </button>
              </div>

              {cartItems?.map((item) => (
                <motion.div
                  key={item._id}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="bg-slate-800 rounded-lg p-6 border border-slate-700"
                >
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <h3 className="text-lg font-semibold text-white mb-1">
                        {item.eventTitle}
                      </h3>
                      <p className="text-slate-400 text-sm mb-2">
                        Ticket Type: {item.ticketType.name}
                      </p>
                      <p className="text-slate-400 text-sm mb-4">
                        {item.ticketType.description}
                      </p>

                      {/* Quantity Controls */}
                      <div className="flex items-center space-x-4">
                        <div className="flex items-center space-x-2">
                          <button
                            onClick={() => handleQuantityChange(item._id, item.quantity - 1)}
                            className="w-8 h-8 bg-slate-700 hover:bg-slate-600 rounded-full flex items-center justify-center transition-colors"
                          >
                            <FiMinus className="w-4 h-4" />
                          </button>
                          <span className="w-8 text-center font-semibold">
                            {item.quantity}
                          </span>
                          <button
                            onClick={() => handleQuantityChange(item._id, item.quantity + 1)}
                            className="w-8 h-8 bg-slate-700 hover:bg-slate-600 rounded-full flex items-center justify-center transition-colors"
                          >
                            <FiPlus className="w-4 h-4" />
                          </button>
                        </div>

                        <button
                          onClick={() => handleRemoveItem(item._id)}
                          className="text-red-400 hover:text-red-300 transition-colors flex items-center space-x-1"
                        >
                          <FiTrash2 className="w-4 h-4" />
                          <span className="text-sm">Remove</span>
                        </button>
                      </div>
                    </div>

                    <div className="text-right">
                      <p className="text-slate-400 text-sm">Price per ticket</p>
                      <p className="text-xl font-bold text-white mb-2">
                        ${item.ticketType.price}
                      </p>
                      <p className="text-slate-400 text-sm">Subtotal</p>
                      <p className="text-xl font-bold text-blue-400">
                        ${(item.ticketType.price * item.quantity).toFixed(2)}
                      </p>
                    </div>
                  </div>
                </motion.div>
              ))}
            </div>

            {/* Order Summary */}
            <div className="lg:col-span-1">
              <motion.div
                initial={{ opacity: 0, x: 20 }}
                animate={{ opacity: 1, x: 0 }}
                className="bg-slate-800 rounded-lg p-6 border border-slate-700 sticky top-8"
              >
                <h2 className="text-xl font-bold mb-6">Order Summary</h2>

                <div className="space-y-4 mb-6">
                  <div className="flex justify-between">
                    <span className="text-slate-400">Items ({cartItems?.length || 0})</span>
                    <span className="text-white">${calculateTotal().toFixed(2)}</span>
                  </div>

                  <div className="flex justify-between">
                    <span className="text-slate-400">Service Fee</span>
                    <span className="text-white">$2.50</span>
                  </div>

                  <div className="border-t border-slate-700 pt-4">
                    <div className="flex justify-between">
                      <span className="text-lg font-semibold text-white">Total</span>
                      <span className="text-lg font-bold text-blue-400">
                        ${(calculateTotal() + 2.50).toFixed(2)}
                      </span>
                    </div>
                  </div>
                </div>

                <button
                  onClick={handleCheckout}
                  className="w-full bg-blue-600 hover:bg-blue-700 text-white py-3 rounded-lg font-semibold transition-colors mb-4"
                >
                  Proceed to Checkout
                </button>

                <button
                  onClick={() => navigate('/')}
                  className="w-full bg-slate-700 hover:bg-slate-600 text-white py-3 rounded-lg font-semibold transition-colors"
                >
                  Continue Shopping
                </button>
              </motion.div>
            </div>
          </div>
        )}
      </div>

      {/* Payment Modal */}
      {showPaymentModal && (
        <MultiEventPaymentModal
          isOpen={showPaymentModal}
          onClose={() => setShowPaymentModal(false)}
        />
      )}
    </div>
  )
}

client/pages/CreateEvent.jsx.content:
import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import {
  FiCheck,
  FiFileText,
  FiCalendar,
  FiMapPin,
  FiUsers,
  FiImage,
  FiUpload,
  FiCopy,
  FiInfo,
} from "react-icons/fi";
import toast from "react-hot-toast";
import { useNavigate, useLocation } from "react-router-dom";
import {
  resizeImage,
  isValidImage,
  getFileSizeInMB,
  validateImageFile,
  compressImage,
} from "../utils/imageUtils";
import CustomCalendar from "../components/CustomCalendar";
import TicketModal from "../components/TicketModal";

export default function CreateEvent() {
  const [eventType, setEventType] = useState(null);
  const [selectedImage, setSelectedImage] = useState(null);
  const [imagePreview, setImagePreview] = useState(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showStartCalendar, setShowStartCalendar] = useState(false);
  const [showEndCalendar, setShowEndCalendar] = useState(false);
  const [ticketModalOpen, setTicketModalOpen] = useState(false);
  const [editingTicket, setEditingTicket] = useState(null);
  const [formData, setFormData] = useState({
    title: "",
    venueName: "",
    address: "",
    startDate: "",
    endDate: "",
    eventDate: "",
    eventTime: "",
    eventEndDate: "",
    eventEndTime: "",
    description: "",
    isRecurring: false,
    ticketPrice: "",
    maxAttendees: "",
    capacity: "",
    category: "",
    showOnExplore: false,
    eventType: "",
    status: "",
    price: "",
    location: "",
    venue: "",
    // Event-level password protection
    enableSkipLine: false,
    passwordProtect: false,
    eventPassword: "",
  });

  const [tickets, setTickets] = useState([]);

  const navigate = useNavigate();
  const location = useLocation();
  const [isDuplicateMode, setIsDuplicateMode] = useState(false);

  // Check user authentication and role on component mount
  useEffect(() => {
    const token =
      localStorage.getItem("token") || localStorage.getItem("authToken");
    const user = JSON.parse(localStorage.getItem("user") || "{}");

    if (!token) {
      toast.error("Please login first to create events");
      navigate("/login");
      return;
    }

    if (user.role !== "organizer") {
      toast.error(
        "Only organizers can create events. Please login as an organizer.",
      );
      navigate("/login");
      return;
    }
  }, [navigate]);

  // Handle duplicate mode - load pre-filled data
  useEffect(() => {
    const urlParams = new URLSearchParams(location.search);
    const duplicate = urlParams.get('duplicate');

    if (duplicate === 'true') {
      setIsDuplicateMode(true);
      const duplicateEventData = localStorage.getItem('duplicateEventData');

      if (duplicateEventData) {
        try {
          const eventData = JSON.parse(duplicateEventData);
          console.log('Loading duplicate event data:', eventData);
          console.log('Event category:', eventData.category);
          console.log('Event ticket types:', eventData.ticketTypes);
          console.log('Event maxAttendees:', eventData.maxAttendees);

          // Pre-fill ALL form data including dates, capacity, venue, etc.
          const totalCapacity = eventData.ticketTypes 
            ? eventData.ticketTypes.reduce((total, ticket) => total + (ticket.quantity || 0), 0)
            : (eventData.maxAttendees || eventData.capacity || "");

          setFormData({
            title: eventData.title || "",
            venueName: eventData.venueName || eventData.venue || "",
            address: eventData.address || eventData.location || "",
            startDate: eventData.startDate || "", // Booking start date
            endDate: eventData.endDate || "", // Booking end date
            eventDate: eventData.eventDate || eventData.startDate || "", // Actual event date
            eventTime: eventData.eventTime || "18:00", // Default event time
            eventEndDate: eventData.eventEndDate || eventData.endDate || "", // Actual event end date
            eventEndTime: eventData.eventEndTime || "22:00", // Default event end time
            description: eventData.description || "",
            isRecurring: eventData.isRecurring || false,
            ticketPrice: eventData.ticketPrice || eventData.price || "",
            maxAttendees: totalCapacity,
            capacity: totalCapacity,
            category: eventData.category || "", // This should now work properly
            showOnExplore: eventData.showOnExplore || false,
            eventType: eventData.eventType || "",
            status: eventData.status || "",
            price: eventData.price || eventData.ticketPrice || "",
            location: eventData.location || eventData.address || "",
            venue: eventData.venue || eventData.venueName || "",
            // Event-level password protection
            enableSkipLine: eventData.enableSkipLine || false,
            passwordProtect: eventData.passwordProtect || false,
            eventPassword: eventData.eventPassword || "",
          });

          // Pre-fill tickets if they exist
          if (eventData.tickets && Array.isArray(eventData.tickets)) {
            const duplicatedTickets = eventData.tickets.map(ticket => ({
              ...ticket,
              id: Date.now() + Math.random(), // Generate new IDs for duplicated tickets
              sold: 0, // Reset sold count for new event
            }));
            setTickets(duplicatedTickets);
          }

          // Set event type if it exists, default to 'ticketed' if not specified
          if (eventData.eventType) {
            setEventType(eventData.eventType);
          } else if (eventData.tickets && eventData.tickets.length > 0) {
            setEventType('ticketed');
          } else {
            setEventType('rsvp');
          }

          // Handle image duplication if exists
          if (eventData.image || eventData.imageUrl) {
            const imageUrl = eventData.image || eventData.imageUrl;
            setImagePreview(imageUrl);
            // Note: We can't set selectedImage file object, but we can show the preview
          }

          // Clear the duplicate data from localStorage after loading
          localStorage.removeItem('duplicateEventData');

          toast.success('Event data loaded for duplication. All fields have been pre-filled - please review and update as needed.');
        } catch (error) {
          console.error('Error loading duplicate event data:', error);
          toast.error('Failed to load event data for duplication');
        }
      }
    }
  }, [location]);

  // Cleanup function for object URLs to prevent memory leaks
  useEffect(() => {
    return () => {
      if (imagePreview && imagePreview.startsWith("blob:")) {
        URL.revokeObjectURL(imagePreview);
      }
    };
  }, [imagePreview]);

  const handleInputChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: type === "checkbox" ? checked : value,
    }));
  };

  const addTicket = () => {
    setEditingTicket(null);
    setTicketModalOpen(true);
  };

  const editTicket = (ticket) => {
    setEditingTicket(ticket);
    setTicketModalOpen(true);
  };

  const removeTicket = (ticketId) => {
    setTickets(tickets.filter((ticket) => ticket.id !== ticketId));
    toast.success("Ticket removed successfully");
  };

  const handleTicketSave = (ticketData) => {
    if (editingTicket) {
      setTickets(
        tickets.map((ticket) =>
          ticket.id === editingTicket.id ? ticketData : ticket,
        ),
      );
    } else {
      setTickets([...tickets, ticketData]);
    }
    setTicketModalOpen(false);
    setEditingTicket(null);
  };

  const addTicketGroup = () => {
    const groupTickets = [
      {
        id: Date.now(),
        name: "Early Bird",
        description: "Early access discount - limited time offer",
        price: 25,
        quantity: 50,
        isActive: true,
        enableEarlyBird: true,
        availability: "Available",
        maxCartQty: 5,
      },
      {
        id: Date.now() + 1,
        name: "General Admission",
        description: "Standard event entry",
        price: 35,
        quantity: 200,
        isActive: true,
        availability: "Available",
        maxCartQty: 10,
      },
      {
        id: Date.now() + 2,
        name: "VIP Experience",
        description: "Premium access with special perks",
        price: 75,
        quantity: 25,
        isActive: true,
        enableSkipLine: true,
        availability: "Available",
        maxCartQty: 4,
      },
    ];
    setTickets([...tickets, ...groupTickets]);
    toast.success(
      "Added 3 ticket types: Early Bird, General Admission, and VIP Experience",
    );
  };

  const handleImageChange = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    // Enhanced validation with user-friendly messages
    const validation = validateImageFile(file, 10); // 10MB limit
    if (!validation.isValid) {
      toast.error(validation.message);
      return;
    }

    try {
      // Show loading toast for large files
      const fileSizeMB = getFileSizeInMB(file);
      if (fileSizeMB > 2) {
        toast.loading(
          `Processing large image (${fileSizeMB}MB)... Please wait.`,
        );
      }

      // Create immediate preview
      const previewUrl = URL.createObjectURL(file);
      setImagePreview(previewUrl);

      // Compress image for better performance and smaller payload
      const compressedImage = await compressImage(file, 1200, 800, 0.8, 500);

      // Create a blob from the base64 string
      const compressedBlob = await fetch(compressedImage).then((r) => r.blob());
      const compressedFile = new File([compressedBlob], file.name, {
        type: file.type,
      });

      setSelectedImage(compressedFile);

      // Store compressed base64 for submission
      setFormData((prev) => ({ ...prev, imageData: compressedImage }));

      toast.dismiss(); // Remove loading toast
      toast.success("Image uploaded successfully!");
    } catch (error) {
      console.error("Error processing image:", error);
      toast.dismiss(); // Remove loading toast
      toast.error(
        "Error processing image. Please try a smaller image or different format.",
      );
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      // Validate required fields
      if (
        !formData.title ||
        !formData.venueName ||
        !formData.startDate ||
        !formData.endDate
      ) {
        toast.error("Please fill in all required fields");
        return;
      }

      // For unified system, tickets are optional but recommended
      // Remove strict validation to allow both RSVP and ticketed events to have tickets

      // Prepare form data for submission
      const eventData = {
        title: formData.title,
        description: formData.description,
        venue: formData.venueName,
        address: formData.address,
        startDate: formData.startDate, // Booking start date
        endDate: formData.endDate, // Booking end date
        eventDate: formData.eventDate, // Actual event date
        eventTime: formData.eventTime, // Actual event time
        eventEndDate: formData.eventEndDate, // Actual event end date
        eventEndTime: formData.eventEndTime, // Actual event end time
        category: formData.category || "General",
        locationType: "physical",
        status: "draft",
        isPublic: formData.showOnExplore,
        allowRefunds: true,
        eventType: eventType, // Fix: Include the actual eventType
        // Use actual uploaded image data
        image: formData.imageData || null,
        // Event-level password protection
        enableSkipLine: formData.enableSkipLine,
        passwordProtect: formData.passwordProtect,
        eventPassword: formData.passwordProtect ? formData.eventPassword : null,
        ticketTypes: tickets.map((ticket) => ({
          name: ticket.name,
          description: ticket.description,
          price: parseFloat(ticket.price) || 0,
          quantity: parseInt(ticket.quantity) || 0,
          sold: 0,
          isActive: ticket.isActive !== false, // Default to true
          availability: ticket.availability || "Available",
          maxCartQty: parseInt(ticket.maxCartQty) || 10,
          saleStartDate: new Date().toISOString(),
          saleEndDate: formData.endDate,
          perks: [],
          // Include all additional settings
          enableSkipLine: ticket.enableSkipLine || false,
          passwordProtect: ticket.passwordProtect || false,
          enableBundle: ticket.enableBundle || false,
          enableEarlyBird: ticket.enableEarlyBird || false,
          coverTicket: ticket.coverTicket || false,
          enableComboTickets: ticket.enableComboTickets || false,
          enableWaitlist: ticket.enableWaitlist || false,
          hideTicket: ticket.hideTicket || false,
          bundlePrice: ticket.bundlePrice || null,
          waitlistTicket: ticket.waitlistTicket || "",
          ticketPassword: ticket.ticketPassword || "",
          earlyBirdPrice: ticket.earlyBirdPrice || null,
          earlyBirdEndDate: ticket.earlyBirdEndDate || "",
          creditPrice: ticket.creditPrice || null,
          displayPrice: ticket.displayPrice || ticket.price || 0,
        })),
        totalRevenue: 0,
        totalTicketsSold: 0,
        views: 0,
        uniqueViews: 0,
        socialShares: 0,
      };

      // Submit to backend
      const token =
        localStorage.getItem("token") || localStorage.getItem("authToken");
      const user = JSON.parse(localStorage.getItem("user") || "{}");

      if (!token) {
        toast.error("Please login first to create events");
        navigate("/login");
        return;
      }

      if (user.role !== "organizer") {
        toast.error(
          "Only organizers can create events. Please login as an organizer.",
        );
        navigate("/login");
        return;
      }

      console.log("Creating event with data:", eventData);
      console.log("User role:", user.role);
      console.log("Token exists:", !!token);

      const response = await fetch("/api/organizer/events", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(eventData),
      });

      if (response.ok) {
        const newEvent = await response.json();
        toast.success("Event created successfully!");
        // Clear form data
        setFormData({
          title: "",
          venueName: "",
          address: "",
          startDate: "",
          endDate: "",
          eventDate: "",
          eventTime: "",
          eventEndDate: "",
          eventEndTime: "",
          description: "",
          isRecurring: false,
          ticketPrice: "",
          maxAttendees: "",
          category: "",
          showOnExplore: false,
        });
        setTickets([]);
        setSelectedImage(null);
        setImagePreview(null);
        setEventType(null);
        // Redirect to events page
        navigate("/organizer/events");
      } else {
        let errorMessage = "Unknown error occurred";
        try {
          const error = await response.json();
          errorMessage =
            error.message || error.error || "Failed to create event";
        } catch (parseError) {
          // If response is not JSON, use status text
          errorMessage = `Server error: ${response.status} ${response.statusText}`;
        }

        if (response.status === 401) {
          toast.error(
            "Your session has expired. Please login again as an organizer.",
          );
          localStorage.removeItem("token");
          localStorage.removeItem("authToken");
          localStorage.removeItem("user");
          navigate("/login");
        } else if (response.status === 403) {
          toast.error(
            "You don't have permission to create events. Please login as an organizer.",
          );
          navigate("/login");
        } else {
          toast.error(`Error creating event: ${errorMessage}`);
          console.error("Event creation error:", {
            status: response.status,
            statusText: response.statusText,
            message: errorMessage,
          });
        }
      }
    } catch (error) {
      console.error("Error creating event:", error);
      toast.error("Failed to create event. Please try again.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleEventTypeSelect = (type) => {
    setEventType(type);
  };

  const handleBack = () => {
    setEventType(null);
  };

  // Event Type Selection Screen
  if (!eventType) {
    return (
