                  TICKETED
                </span>
              </motion.button>
            </div>
          </motion.div>
        </div>
      </div>
    );
  }

  // Form Screen
  return (
    <div className="min-h-screen bg-black px-4 py-4 sm:py-8">
      <div className="max-w-6xl mx-auto">
        <div className="flex flex-col lg:flex-row gap-4 sm:gap-8">
