                                  className="text-red-400 hover:text-red-300 text-sm"
                                >
                                  Remove
                                </button>
                              </div>
                            </div>
                            <div className="mt-2 text-gray-400 text-sm">
                              {ticket.description || "No description"}
                            </div>
                            <div className="mt-2 text-white text-sm">
                              <span className="font-medium">
                                Price: ${ticket.price || "0"}
                              </span>
                              <span className="mx-2">•</span>
                              <span className="font-medium">
                                Quantity: {ticket.quantity || "0"}
                              </span>
                            </div>
                          </div>
                        ))
                      )}
                    </div>
                  </div>
                </div>
              </div>

              {/* Additional Settings */}
              <div className="space-y-4">
                <h3 className="text-white font-semibold text-lg">
                  Additional Settings
                </h3>

                <div className="bg-gray-800 border border-gray-600 rounded-lg p-4 space-y-4">
                  {/* Enable Skip the Line */}
                  <div className="flex items-center justify-between">
                    <div className="flex items-center space-x-3">
                      <input
                        type="checkbox"
                        id="enableSkipLine"
                        name="enableSkipLine"
                        checked={formData.enableSkipLine}
                        onChange={handleInputChange}
                        className="w-4 h-4 text-blue-600 bg-gray-700 border-gray-600 rounded focus:ring-blue-500 focus:ring-2"
                      />
                      <label htmlFor="enableSkipLine" className="text-white font-medium">
                        Enable Skip the Line
                      </label>
                      <div className="relative group">
                        <FiInfo className="w-4 h-4 text-gray-400 cursor-help" />
                        <div className="absolute bottom-6 left-0 hidden group-hover:block bg-gray-900 text-white text-xs rounded px-2 py-1 whitespace-nowrap">
                          Allow attendees to skip waiting lines
                        </div>
                      </div>
                    </div>
                  </div>

                  {/* Password Protect */}
                  <div className="space-y-3">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center space-x-3">
                        <input
                          type="checkbox"
                          id="passwordProtect"
                          name="passwordProtect"
                          checked={formData.passwordProtect}
                          onChange={handleInputChange}
                          className="w-4 h-4 text-blue-600 bg-gray-700 border-gray-600 rounded focus:ring-blue-500 focus:ring-2"
                        />
                        <label htmlFor="passwordProtect" className="text-white font-medium">
                          Password Protect
                        </label>
                        <div className="relative group">
                          <FiInfo className="w-4 h-4 text-gray-400 cursor-help" />
                          <div className="absolute bottom-6 left-0 hidden group-hover:block bg-gray-900 text-white text-xs rounded px-2 py-1 whitespace-nowrap">
                            Require password to access this event
                          </div>
                        </div>
                      </div>
                    </div>

                    {/* Password Input - Show only when password protect is enabled */}
                    {formData.passwordProtect && (
                      <div className="ml-7">
                        <input
                          type="password"
                          name="eventPassword"
                          value={formData.eventPassword}
                          onChange={handleInputChange}
                          placeholder="Enter Password"
                          required={formData.passwordProtect}
                          className="w-full bg-gray-700 border border-gray-600 rounded-lg px-4 py-2 text-white placeholder-gray-400 focus:outline-none focus:border-blue-500"
                        />
                      </div>
                    )}
                  </div>
                </div>
              </div>

              {/* Create Event Button */}
              <motion.button
                type="submit"
                onClick={handleSubmit}
                disabled={isSubmitting}
                className={`w-full font-bold py-4 px-6 rounded-lg transition-colors text-lg ${
                  isSubmitting
                    ? "bg-gray-600 text-gray-300 cursor-not-allowed"
                    : "bg-white text-black hover:bg-gray-200"
                }`}
                whileHover={!isSubmitting ? { scale: 1.02 } : {}}
                whileTap={!isSubmitting ? { scale: 0.98 } : {}}
              >
                {isSubmitting ? "CREATING EVENT..." : "CREATE EVENT"}
              </motion.button>
            </motion.div>
          </div>
        </div>
      </div>

      {/* Calendar Modals */}
      <CustomCalendar
        isOpen={showStartCalendar}
        onClose={() => setShowStartCalendar(false)}
        selectedDate={formData.startDate}
        onDateSelect={(date) =>
          setFormData((prev) => ({ ...prev, startDate: date }))
        }
        label="Start Time"
      />

      <CustomCalendar
        isOpen={showEndCalendar}
        onClose={() => setShowEndCalendar(false)}
        selectedDate={formData.endDate}
        onDateSelect={(date) =>
          setFormData((prev) => ({ ...prev, endDate: date }))
        }
        label="End Time"
      />

      {/* Ticket Modal */}
      <TicketModal
        isOpen={ticketModalOpen}
        onClose={() => setTicketModalOpen(false)}
        onSave={handleTicketSave}
        ticket={editingTicket}
      />
    </div>
  );
}

