            onChange={handleChange}
            required
            className="w-full border border-white text-white text-xs sm:text-sm md:text-base px-2 sm:px-3 py-2 sm:py-3 rounded-md bg-transparent focus:outline-none focus:border-white/70"
          />
          <input
            name="phone"
