// Frontend Authentication Service
class AuthService {
  constructor() {
    this.baseURL = '';
    this.token = localStorage.getItem('token');
  }

  // Get auth headers for API requests
  getAuthHeaders() {
    const token = localStorage.getItem('token');
    return {
      'Content-Type': 'application/json',
      ...(token && { 'Authorization': `Bearer ${token}` })
    };
  }

  // Check if user is authenticated
  isAuthenticated() {
    const token = localStorage.getItem('token');
    const user = this.getCurrentUser();
    return !!(token && user);
  }

  // Get current user from localStorage
  getCurrentUser() {
    try {
      const user = localStorage.getItem('user');
      return user ? JSON.parse(user) : null;
    } catch (error) {
      console.error('Error parsing user data:', error);
      return null;
    }
  }

  // Login user
  async login(credentials) {
    try {
      const response = await fetch('/api/auth/login', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(credentials),
      });

      const data = await response.json();

      if (response.ok) {
        this.setAuthData(data);
        return { success: true, data };
      } else {
        return { success: false, error: data.message || 'Login failed' };
      }
    } catch (error) {
      console.error('Login error:', error);
      return { success: false, error: 'Network error' };
    }
  }

  // Register user
  async register(userData) {
    try {
      const response = await fetch('/api/auth/register', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(userData),
      });

      const data = await response.json();

      if (response.ok) {
        this.setAuthData(data);
        return { success: true, data };
      } else {
        return { success: false, error: data.message || 'Registration failed' };
      }
    } catch (error) {
      console.error('Registration error:', error);
      return { success: false, error: 'Network error' };
    }
  }

  // Set authentication data
  setAuthData(data) {
    // Handle both token formats for compatibility
    const token = data.accessToken || data.token;
    if (token) {
      localStorage.setItem('token', token);
      this.token = token;
    }
    if (data.refreshToken) {
      localStorage.setItem('refreshToken', data.refreshToken);
    }
    if (data.user) {
      localStorage.setItem('user', JSON.stringify(data.user));
    }
  }

  // Logout user
  logout() {
    localStorage.removeItem('token');
    localStorage.removeItem('refreshToken');
    localStorage.removeItem('user');
    this.token = null;
    // Don't auto-redirect - let the app handle it
  }

  // Refresh token (no expiration - tokens are persistent)
  async refreshToken() {
    // With no token expiration, just return the current token
    const currentToken = localStorage.getItem('token');
    if (currentToken) {
      return { success: true, data: { accessToken: currentToken } };
    }

    // If no token exists, user needs to login again
    return { success: false, error: 'No token available' };
  }

  // Make authenticated API request (no token expiration)
  async apiRequest(url, options = {}) {
    const headers = this.getAuthHeaders();

    try {
      const response = await fetch(url, {
        ...options,
        headers: {
          ...headers,
          ...options.headers,
        },
      });

      // Log response for debugging
      if (!response.ok) {
        console.log(`API Request failed: ${response.status} ${response.statusText} for ${url}`);
      }

      return response;
    } catch (error) {
      console.error('API request error:', error);
      throw error;
    }
  }

  // Check user role
  hasRole(requiredRole) {
    const user = this.getCurrentUser();
    return user && user.role === requiredRole;
  }

  // Check if user is organizer
  isOrganizer() {
    return this.hasRole('organizer');
  }

  // Check if user is attendee
  isAttendee() {
    return this.hasRole('attendee');
  }
}

// Create singleton instance
export const authService = new AuthService();
export default authService;

