// ==================== FINANCIAL SCHEMA ====================
export const payoutSchema = {
  _id: { type: 'ObjectId', auto: true },
  organizerId: { type: 'ObjectId', required: true, ref: 'auth_users' },
  eventId: { type: 'ObjectId', required: true, ref: 'events' },

