};

// ==================== TEAM MANAGEMENT SCHEMA ====================
export const teamMemberSchema = {
  _id: { type: 'ObjectId', auto: true },
  organizerId: { type: 'ObjectId', required: true, ref: 'auth_users' },
  organizationId: { type: 'ObjectId', required: true, ref: 'organizations' },

