  async getSupportTickets(organizerId, status = null) {
    await this.connect();
    const query = { organizerId: new ObjectId(organizerId) };
    if (status) query.status = status;

    return await this.db.collection('support_tickets')
      .find(query)
      .sort({ createdAt: -1 })
      .toArray();
