          ...eventData,
          organizerId,
          organizationId
        });
        createdEvents.push(event);
        console.log(`[Sample Data] Created event: ${event.title}`);
      }

      // Create sample attendees for events
      for (const event of createdEvents) {
        for (const attendeeData of this.sampleAttendees) {
          await organizerStorage.createAttendee({
            ...attendeeData,
            eventId: event._id,
            organizerId,
            userId: event._id // Using event ID as placeholder user ID
          });
        }
      }

      // Create sample bookings for events
      for (const event of createdEvents) {
        for (let i = 0; i < this.sampleAttendees.length; i++) {
          const attendeeData = this.sampleAttendees[i];
          const bookingData = {
            _id: new ObjectId(),
            bookingId: `BK-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
            paymentIntentId: `pi_${Math.random().toString(36).substr(2, 24)}`,
            eventId: event._id.toString(),
            eventTitle: event.title,
            attendeeName: `${attendeeData.firstName} ${attendeeData.lastName}`,
            attendeeEmail: attendeeData.email,
            ticketType: event.ticketTypes[0]?.name || 'General Admission',
            quantity: Math.floor(Math.random() * 3) + 1, // 1-3 tickets
            ticketPrice: event.ticketTypes[0]?.price || 50,
            totalAmount: (event.ticketTypes[0]?.price || 50) * (Math.floor(Math.random() * 3) + 1),
            platformFee: 2.50,
            processingFee: 1.00,
            status: ['confirmed', 'pending', 'cancelled'][Math.floor(Math.random() * 3)],
            paymentStatus: ['paid', 'pending', 'failed'][Math.floor(Math.random() * 3)],
            bookingDate: new Date(Date.now() - Math.random() * 30 * 24 * 60 * 60 * 1000), // Random date within last 30 days
            createdAt: new Date(),
            updatedAt: new Date()
          };

          // Insert directly into MongoDB bookings collection
          await organizerStorage.connect();
          await organizerStorage.db.collection('bookings').insertOne(bookingData);
        }
      }

      // Create sample marketing campaigns
      for (const campaignData of this.sampleMarketingCampaigns) {
        await organizerStorage.createMarketingCampaign({
          ...campaignData,
          organizerId,
          eventId: createdEvents[0]._id
        });
      }

      // Create sample audience members
      for (const audienceData of this.sampleAudience) {
        await organizerStorage.createAudienceMember({
          ...audienceData,
          organizerId
        });
      }

      // Create sample team members
      for (const memberData of this.sampleTeamMembers) {
        await organizerStorage.createTeamMember({
          ...memberData,
          organizerId,
          organizationId
        });
      }

      // Create sample payouts
      for (const payoutData of this.samplePayouts) {
        await organizerStorage.createPayout({
          ...payoutData,
          organizerId,
          eventId: createdEvents[0]._id
        });
      }

      // Create sample disputes
      for (const disputeData of this.sampleDisputes) {
        await organizerStorage.createDispute({
          ...disputeData,
          organizerId,
          eventId: createdEvents[0]._id,
          attendeeId: createdEvents[0]._id // Using event ID as placeholder
        });
      }

      // Create sample support tickets
      for (const ticketData of this.sampleSupportTickets) {
        await organizerStorage.createSupportTicket({
          ...ticketData,
          organizerId
        });
      }

      // Create sample analytics
      for (const analyticsData of this.sampleAnalytics) {
        await organizerStorage.createAnalyticsEntry({
          ...analyticsData,
          organizerId,
          eventId: createdEvents[0]._id
        });
      }

      console.log(`[Sample Data] Successfully generated complete sample data for organizer`);
      return {
        message: "Sample data generated successfully",
        events: createdEvents.length,
        attendees: this.sampleAttendees.length * createdEvents.length,
        bookings: this.sampleAttendees.length * createdEvents.length,
        campaigns: this.sampleMarketingCampaigns.length,
        audience: this.sampleAudience.length,
        teamMembers: this.sampleTeamMembers.length,
        payouts: this.samplePayouts.length,
        disputes: this.sampleDisputes.length,
        supportTickets: this.sampleSupportTickets.length,
        analytics: this.sampleAnalytics.length
      };

    } catch (error) {
      console.error('[Sample Data] Generation error:', error);
      throw error;
    }
  }

  async clearAllData(organizerId) {
    try {
      console.log(`[Sample Data] Clearing all data for organizer: ${organizerId}`);

      // This would require implementing delete methods in storage service
      // For now, we'll just log the intent
      console.log(`[Sample Data] Data clearing not yet implemented`);

      return { message: "Data clearing not yet implemented" };
    } catch (error) {
      console.error('[Sample Data] Clear data error:', error);
      throw error;
    }
  }
}

export const sampleDataService = new SampleDataService();

server/services/smsService.js.content:
import twilio from 'twilio';

class SMSService {
  constructor() {
    this.client = twilio(
      process.env.TWILIO_ACCOUNT_SID,
      process.env.TWILIO_AUTH_TOKEN
    );
    this.fromNumber = process.env.TWILIO_PHONE_NUMBER;
  }

  async sendOTP(phoneNumber, otp) {
    const message = `Your Event Management Platform verification code is: ${otp}. This code expires in 10 minutes.`;

    try {
      const result = await this.client.messages.create({
        body: message,
        from: this.fromNumber,
        to: phoneNumber
      });

      console.log('OTP SMS sent:', result.sid);
      return { success: true, messageSid: result.sid };
    } catch (error) {
      console.error('Error sending OTP SMS:', error);
      return { success: false, error: error.message };
    }
  }

  async sendPhoneChangeNotification(phoneNumber, userName) {
    const message = `Hi ${userName}, your phone number has been successfully updated on Event Management Platform. If this wasn't you, please contact support immediately.`;

    try {
      const result = await this.client.messages.create({
        body: message,
        from: this.fromNumber,
        to: phoneNumber
      });

      console.log('Phone change notification sent:', result.sid);
      return { success: true, messageSid: result.sid };
    } catch (error) {
      console.error('Error sending phone change notification:', error);
      return { success: false, error: error.message };
    }
  }

  async sendSecurityAlert(phoneNumber, userName, activity) {
    const message = `Security Alert: ${activity} detected on your Event Management Platform account (${userName}). If this wasn't you, secure your account immediately.`;

    try {
      const result = await this.client.messages.create({
        body: message,
        from: this.fromNumber,
        to: phoneNumber
      });

      console.log('Security alert SMS sent:', result.sid);
      return { success: true, messageSid: result.sid };
    } catch (error) {
      console.error('Error sending security alert SMS:', error);
      return { success: false, error: error.message };
    }
  }
}

export const smsService = new SMSService();

