import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { 
  FiCalendar, 
  FiSearch, 
  FiFilter,
  FiEdit,
  FiTrash2,
  FiEye,
  FiPlus,
  FiDownload,
  FiMoreVertical,
  FiMapPin,
  FiClock,
  FiDollarSign,
  FiUsers,
  FiUser
} from "react-icons/fi";
import { X } from "lucide-react";
import toast from "react-hot-toast";

export default function AdminEventsManagement() {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [filterStatus, setFilterStatus] = useState("all");
  const [currentPage, setCurrentPage] = useState(1);
  const eventsPerPage = 10;

  // Modal states
  const [viewModal, setViewModal] = useState({ isOpen: false, event: null });
  const [editModal, setEditModal] = useState({ isOpen: false, event: null });
  const [deleteModal, setDeleteModal] = useState({ isOpen: false, event: null });
  const [bookingsModal, setBookingsModal] = useState({ isOpen: false, event: null, bookings: [], loading: false });
  const [actionLoading, setActionLoading] = useState(false);

  // Form states
  const [editForm, setEditForm] = useState({
    title: '',
    description: '',
    venue: '',
    startDate: '',
    endDate: '',
    status: '',
    category: ''
  });

  useEffect(() => {
    fetchEvents();
  }, []);

  const fetchEvents = async () => {
    try {
      const token = localStorage.getItem("adminToken");

      // Check if token exists
      if (!token) {
        toast.error("Admin authentication required");
        return;
      }

      const response = await fetch("/api/admin/events", {
        headers: {
          "Authorization": `Bearer ${token}`,
          "Content-Type": "application/json"
        }
      });

      if (response.ok) {
        const data = await response.json();
        setEvents(data);
      } else if (response.status === 401) {
        toast.error("Session expired. Please login again.");
        localStorage.removeItem("adminToken");
        localStorage.removeItem("adminUser");
        window.location.href = "/admin-login";
      } else {
        toast.error("Failed to fetch events");
      }
    } catch (error) {
      console.error("Error fetching events:", error);
      toast.error("Failed to fetch events");
    } finally {
      setLoading(false);
    }
  };

  // Action handlers
  const handleViewEvent = async (event) => {
    try {
      const token = localStorage.getItem("adminToken");
      const response = await fetch(`/api/admin/events/${event.id}`, {
        headers: {
          "Authorization": `Bearer ${token}`,
          "Content-Type": "application/json"
        }
      });
      if (response.ok) {
        const eventData = await response.json();
        setViewModal({ isOpen: true, event: eventData });
      } else {
        toast.error("Failed to fetch event details");
      }
    } catch (error) {
      console.error("Error fetching event details:", error);
      toast.error("Failed to fetch event details");
    }
  };

  const handleEditEvent = async (event) => {
    try {
      const token = localStorage.getItem("adminToken");
      const response = await fetch(`/api/admin/events/${event.id}`, {
        headers: {
          "Authorization": `Bearer ${token}`,
          "Content-Type": "application/json"
        }
      });
      if (response.ok) {
        const eventData = await response.json();
        setEditForm({
          title: eventData.title || '',
          description: eventData.description || '',
          venue: eventData.venue || '',
          startDate: eventData.startDate ? new Date(eventData.startDate).toISOString().split('T')[0] : '',
          endDate: eventData.endDate ? new Date(eventData.endDate).toISOString().split('T')[0] : '',
          status: eventData.status || 'draft',
          category: eventData.category || ''
        });
        setEditModal({ isOpen: true, event: eventData });
      } else {
        toast.error("Failed to fetch event details");
      }
    } catch (error) {
      console.error("Error fetching event details:", error);
      toast.error("Failed to fetch event details");
    }
  };

  const handleDeleteEvent = (event) => {
    setDeleteModal({ isOpen: true, event });
  };

  const confirmDelete = async () => {
    if (!deleteModal.event) return;

    setActionLoading(true);
    try {
      const token = localStorage.getItem("adminToken");
      const response = await fetch(`/api/admin/events/${deleteModal.event.id}`, {
        method: 'DELETE',
        headers: {
          "Authorization": `Bearer ${token}`,
          "Content-Type": "application/json"
        }
      });

      if (response.ok) {
        setEvents(events.filter(event => event.id !== deleteModal.event.id));
        toast.success("Event deleted successfully");
        setDeleteModal({ isOpen: false, event: null });
      } else {
        toast.error("Failed to delete event");
      }
    } catch (error) {
      console.error("Error deleting event:", error);
      toast.error("Failed to delete event");
    } finally {
      setActionLoading(false);
    }
  };

  const handleUpdateEvent = async (e) => {
    e.preventDefault();
    if (!editModal.event) return;

    setActionLoading(true);
    try {
      const token = localStorage.getItem("adminToken");
      const response = await fetch(`/api/admin/events/${editModal.event.id}`, {
        method: 'PUT',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(editForm)
      });

      if (response.ok) {
        // Update local state
        setEvents(events.map(event => 
          event.id === editModal.event.id 
            ? { ...event, ...editForm }
            : event
        ));
        toast.success("Event updated successfully");
        setEditModal({ isOpen: false, event: null });
      } else {
        toast.error("Failed to update event");
      }
    } catch (error) {
      console.error("Error updating event:", error);
      toast.error("Failed to update event");
    } finally {
      setActionLoading(false);
    }
  };

  const handleStatusUpdate = async (eventId, newStatus, reason = '') => {
    setActionLoading(true);
    try {
      const token = localStorage.getItem("adminToken");
      const response = await fetch(`/api/admin/events/${eventId}/status`, {
        method: "PUT",
        headers: {
          "Authorization": `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ status: newStatus, reason: reason }),
      });

      if (response.ok) {
        setEvents(events.map(e => 
          e.id === eventId ? { ...e, status: newStatus } : e
        ));
        toast.success(`Event status updated to ${newStatus}`);
      } else {
        toast.error("Failed to update event status");
      }
    } catch (error) {
      console.error("Error updating event status:", error);
      toast.error("Failed to update event status");
    } finally {
      setActionLoading(false);
    }
  };

  const handleViewBookings = async (event) => {
    setBookingsModal({ isOpen: true, event, bookings: [], loading: true });

    try {
      const token = localStorage.getItem("adminToken");
      const response = await fetch(`/api/admin/events/${event.id}/bookings`, {
        headers: {
          "Authorization": `Bearer ${token}`,
          "Content-Type": "application/json"
        }
      });
      if (response.ok) {
        const bookingsData = await response.json();
        setBookingsModal(prev => ({ 
          ...prev, 
          bookings: bookingsData, 
          loading: false 
        }));
      } else {
        toast.error("Failed to fetch bookings");
        setBookingsModal(prev => ({ ...prev, loading: false }));
      }
    } catch (error) {
      console.error("Error fetching bookings:", error);
      toast.error("Failed to fetch bookings");
      setBookingsModal(prev => ({ ...prev, loading: false }));
    }
  };

  const filteredEvents = events.filter(event => {
    const matchesSearch = event.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         (event.description && event.description.toLowerCase().includes(searchTerm.toLowerCase())) ||
                         (event.venue && event.venue.toLowerCase().includes(searchTerm.toLowerCase()));
    const matchesStatus = filterStatus === "all" || event.status === filterStatus;
    return matchesSearch && matchesStatus;
  });

  const indexOfLastEvent = currentPage * eventsPerPage;
  const indexOfFirstEvent = indexOfLastEvent - eventsPerPage;
  const currentEvents = filteredEvents.slice(indexOfFirstEvent, indexOfLastEvent);
  const totalPages = Math.ceil(filteredEvents.length / eventsPerPage);

  const getStatusColor = (status) => {
    switch (status) {
      case "published": return "bg-green-500/20 text-green-400 border-green-500/30";
      case "draft": return "bg-yellow-500/20 text-yellow-400 border-yellow-500/30";
      default: return "bg-gray-500/20 text-gray-400 border-gray-500/30";
    }
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-red-500"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6 max-w-full">
      {/* Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-3xl font-bold text-white">Events Management</h1>
          <p className="text-gray-400 mt-1">Manage all platform events</p>
        </div>
        <div className="flex items-center space-x-3">
          <button className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg flex items-center space-x-2 transition-colors">
            <FiDownload className="w-4 h-4" />
            <span>Export</span>
          </button>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-gray-800 rounded-lg p-4 border border-gray-700">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-gray-400 text-sm">Total Events</p>
              <p className="text-2xl font-bold text-white">{events.length}</p>
            </div>
            <FiCalendar className="w-8 h-8 text-blue-500" />
          </div>
        </div>
        <div className="bg-gray-800 rounded-lg p-4 border border-gray-700">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-gray-400 text-sm">Published</p>
              <p className="text-2xl font-bold text-white">{events.filter(e => e.status === 'published').length}</p>
            </div>
            <FiEye className="w-8 h-8 text-green-500" />
          </div>
        </div>
        <div className="bg-gray-800 rounded-lg p-4 border border-gray-700">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-gray-400 text-sm">Total Revenue</p>
              <p className="text-2xl font-bold text-white">${events.reduce((sum, e) => sum + (e.revenue || 0), 0).toLocaleString()}</p>
            </div>
            <FiDollarSign className="w-8 h-8 text-purple-500" />
          </div>
        </div>
        <div className="bg-gray-800 rounded-lg p-4 border border-gray-700">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-gray-400 text-sm">Tickets Sold</p>
              <p className="text-2xl font-bold text-white">{events.reduce((sum, e) => sum + (e.tickets || 0), 0).toLocaleString()}</p>
            </div>
            <FiUsers className="w-8 h-8 text-orange-500" />
          </div>
        </div>
      </div>

      {/* Filters */}
      <div className="bg-gray-800 rounded-xl p-6 border border-gray-700">
        <div className="flex flex-col sm:flex-row gap-4">
          <div className="flex-1">
            <div className="relative">
              <FiSearch className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
              <input
                type="text"
                placeholder="Search events..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-gray-700 text-white pl-10 pr-4 py-2 rounded-lg border border-gray-600 focus:border-red-500 focus:outline-none"
              />
            </div>
          </div>
          <div className="flex items-center space-x-3">
            <FiFilter className="text-gray-400 w-5 h-5" />
            <select
              value={filterStatus}
              onChange={(e) => setFilterStatus(e.target.value)}
              className="bg-gray-700 text-white px-4 py-2 rounded-lg border border-gray-600 focus:border-red-500 focus:outline-none"
            >
              <option value="all">All Status</option>
              <option value="published">Published</option>
              <option value="draft">Draft</option>
            </select>
          </div>
        </div>
      </div>

      {/* Events Table */}
      <div className="bg-gray-800 rounded-xl border border-gray-700 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full min-w-[800px]">
            <thead className="bg-gray-700">
              <tr>
                <th className="text-left p-4 text-gray-300 font-medium min-w-[200px]">Event</th>
                <th className="text-left p-4 text-gray-300 font-medium min-w-[150px]">Organizer</th>
                <th className="text-left p-4 text-gray-300 font-medium min-w-[120px]">Date</th>
                <th className="text-left p-4 text-gray-300 font-medium min-w-[100px]">Status</th>
                <th className="text-left p-4 text-gray-300 font-medium min-w-[120px]">Tickets</th>
                <th className="text-left p-4 text-gray-300 font-medium min-w-[100px]">Revenue</th>
                <th className="text-left p-4 text-gray-300 font-medium min-w-[120px]">Bookings</th>
              </tr>
            </thead>
            <tbody>
              {currentEvents.map((event) => (
                <motion.tr
                  key={event.id}
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  className="border-t border-gray-700 hover:bg-gray-700/50 transition-colors"
                >
                  <td className="p-4">
                    <div className="flex items-center space-x-3">
                      <div className="w-12 h-12 bg-gradient-to-br from-blue-500 to-purple-500 rounded-lg flex items-center justify-center">
                        <FiCalendar className="w-6 h-6 text-white" />
                      </div>
                      <div>
                        <p className="text-white font-medium">{event.title}</p>
                        <div className="flex items-center text-gray-400 text-sm mt-1">
                          <FiMapPin className="w-4 h-4 mr-1" />
                          <span>{event.venue || 'No venue'}</span>
                        </div>
                      </div>
                    </div>
                  </td>
                  <td className="p-4">
                    <span className="text-gray-300">{event.organizer || 'Unknown'}</span>
                  </td>
                  <td className="p-4">
                    <div className="flex items-center text-gray-400 text-sm">
                      <FiClock className="w-4 h-4 mr-1" />
                      <span>{formatDate(event.startDate)}</span>
                    </div>
                  </td>
                  <td className="p-4">
                    <div className="flex items-center gap-2">
                      <span className={`px-2 py-1 rounded-full text-xs font-medium border ${getStatusColor(event.status)}`}>
                        {event.status}
                      </span>

                      {/* Status Update Dropdown */}
                      <div className="relative">
                        <select
                          onChange={(e) => {
                            if (e.target.value && e.target.value !== event.status) {
                              handleStatusUpdate(event.id, e.target.value);
                            }
                            e.target.value = '';
                          }}
                          className="text-xs bg-gray-700 text-gray-300 border border-gray-600 rounded px-2 py-1"
                          defaultValue=""
                        >
                          <option value="" disabled>Update Status</option>
                          {event.status === 'draft' && (
                            <option value="published">Publish</option>
                          )}
                          {event.status === 'published' && (
                            <option value="draft">Mark as Draft</option>
                          )}
                        </select>
                      </div>
                    </div>
                  </td>
                  <td className="p-4">
                    <div className="text-sm">
                      {(() => {
                        const totalTickets = event.ticketTypes?.reduce((sum, ticket) => sum + (ticket.quantity || 0), 0) || 0;
                        const soldTickets = event.ticketTypes?.reduce((sum, ticket) => sum + (ticket.sold || 0), 0) || 0;
                        return (
                          <>
                            <span className="text-white font-medium">{soldTickets}</span>
                            <span className="text-gray-400">/{totalTickets}</span>
                          </>
                        );
                      })()}
                    </div>
                    <div className="w-24 bg-gray-700 rounded-full h-2 mt-1">
                      <div 
                        className="bg-blue-500 h-2 rounded-full" 
                        style={{ 
                          width: `${(() => {
                            const totalTickets = event.ticketTypes?.reduce((sum, ticket) => sum + (ticket.quantity || 0), 0) || 0;
                            const soldTickets = event.ticketTypes?.reduce((sum, ticket) => sum + (ticket.sold || 0), 0) || 0;
                            return totalTickets ? (soldTickets / totalTickets) * 100 : 0;
                          })()}%` 
                        }}
                      ></div>
                    </div>
                  </td>
                  <td className="p-4">
                    <span className="text-green-400 font-medium">${(event.revenue || 0).toLocaleString()}</span>
                  </td>
                  <td className="p-4">
                    <button 
                      onClick={() => handleViewBookings(event)}
                      className="bg-blue-600 hover:bg-blue-700 text-white px-3 py-1 rounded-lg text-sm font-medium transition-colors flex items-center space-x-1"
                      title="View Bookings & Payments"
                    >
                      <FiUsers className="w-4 h-4" />
                      <span>View Bookings</span>
                    </button>
                  </td>
                </motion.tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between">
          <p className="text-gray-400 text-sm">
            Showing {indexOfFirstEvent + 1} to {Math.min(indexOfLastEvent, filteredEvents.length)} of {filteredEvents.length} events
          </p>
          <div className="flex items-center space-x-2">
            <button
              onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
              disabled={currentPage === 1}
              className="px-3 py-1 rounded bg-gray-700 text-gray-300 hover:bg-gray-600 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              Previous
            </button>
            {[...Array(totalPages)].map((_, i) => (
              <button
                key={i + 1}
                onClick={() => setCurrentPage(i + 1)}
                className={`px-3 py-1 rounded ${
                  currentPage === i + 1 
                    ? 'bg-red-600 text-white' 
                    : 'bg-gray-700 text-gray-300 hover:bg-gray-600'
                }`}
              >
                {i + 1}
              </button>
            ))}
            <button
              onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
              disabled={currentPage === totalPages}
              className="px-3 py-1 rounded bg-gray-700 text-gray-300 hover:bg-gray-600 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              Next
            </button>
          </div>
        </div>
      )}

      {/* View Event Modal */}
      {viewModal.isOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-gray-800 rounded-lg p-6 max-w-2xl w-full mx-4 max-h-[90vh] overflow-y-auto">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-xl font-bold text-white">Event Details</h3>
              <button
                onClick={() => setViewModal({ isOpen: false, event: null })}
                className="text-gray-400 hover:text-white"
              >
                <X size={24} />
              </button>
            </div>

            {viewModal.event && (
              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-300 mb-1">Title</label>
                    <p className="text-white">{viewModal.event.title}</p>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-300 mb-1">Status</label>
                    <p className="text-white">{viewModal.event.status}</p>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-300 mb-1">Venue</label>
                    <p className="text-white">{viewModal.event.venue || 'N/A'}</p>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-300 mb-1">Category</label>
                    <p className="text-white">{viewModal.event.category || 'N/A'}</p>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-300 mb-1">Start Date</label>
                    <p className="text-white">{formatDate(viewModal.event.startDate)}</p>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-300 mb-1">End Date</label>
                    <p className="text-white">{formatDate(viewModal.event.endDate)}</p>
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-300 mb-1">Description</label>
                  <p className="text-white">{viewModal.event.description || 'No description available'}</p>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Edit Event Modal */}
      {editModal.isOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-gray-800 rounded-lg p-6 max-w-2xl w-full mx-4 max-h-[90vh] overflow-y-auto">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-xl font-bold text-white">Edit Event</h3>
              <button
                onClick={() => setEditModal({ isOpen: false, event: null })}
                className="text-gray-400 hover:text-white"
              >
                <X size={24} />
              </button>
            </div>

            <form onSubmit={handleUpdateEvent} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-300 mb-1">Title</label>
                  <input
                    type="text"
                    value={editForm.title}
                    onChange={(e) => setEditForm({...editForm, title: e.target.value})}
                    className="w-full bg-gray-700 text-white px-3 py-2 rounded-lg border border-gray-600 focus:border-red-500 focus:outline-none"
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-300 mb-1">Status</label>
                  <select
                    value={editForm.status}
                    onChange={(e) => setEditForm({...editForm, status: e.target.value})}
                    className="w-full bg-gray-700 text-white px-3 py-2 rounded-lg border border-gray-600 focus:border-red-500 focus:outline-none"
                  >
                    <option value="draft">Draft</option>
                    <option value="published">Published</option>
                    <option value="cancelled">Cancelled</option>
                    <option value="completed">Completed</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-300 mb-1">Venue</label>
                  <input
                    type="text"
                    value={editForm.venue}
                    onChange={(e) => setEditForm({...editForm, venue: e.target.value})}
                    className="w-full bg-gray-700 text-white px-3 py-2 rounded-lg border border-gray-600 focus:border-red-500 focus:outline-none"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-300 mb-1">Category</label>
                  <input
                    type="text"
                    value={editForm.category}
                    onChange={(e) => setEditForm({...editForm, category: e.target.value})}
                    className="w-full bg-gray-700 text-white px-3 py-2 rounded-lg border border-gray-600 focus:border-red-500 focus:outline-none"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-300 mb-1">Start Date</label>
                  <input
                    type="date"
                    value={editForm.startDate}
                    onChange={(e) => setEditForm({...editForm, startDate: e.target.value})}
                    className="w-full bg-gray-700 text-white px-3 py-2 rounded-lg border border-gray-600 focus:border-red-500 focus:outline-none"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-300 mb-1">End Date</label>
                  <input
                    type="date"
                    value={editForm.endDate}
                    onChange={(e) => setEditForm({...editForm, endDate: e.target.value})}
                    className="w-full bg-gray-700 text-white px-3 py-2 rounded-lg border border-gray-600 focus:border-red-500 focus:outline-none"
                  />
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-300 mb-1">Description</label>
                <textarea
                  value={editForm.description}
                  onChange={(e) => setEditForm({...editForm, description: e.target.value})}
                  className="w-full bg-gray-700 text-white px-3 py-2 rounded-lg border border-gray-600 focus:border-red-500 focus:outline-none"
                  rows="4"
                />
              </div>
              <div className="flex justify-end space-x-3">
                <button
                  type="button"
                  onClick={() => setEditModal({ isOpen: false, event: null })}
                  className="px-4 py-2 text-gray-400 hover:text-white"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={actionLoading}
                  className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 disabled:opacity-50"
                >
                  {actionLoading ? 'Updating...' : 'Update Event'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Delete Event Modal */}
      {deleteModal.isOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-gray-800 rounded-lg p-6 max-w-md w-full mx-4">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-xl font-bold text-white">Delete Event</h3>
              <button
                onClick={() => setDeleteModal({ isOpen: false, event: null })}
                className="text-gray-400 hover:text-white"
              >
                <X size={24} />
              </button>
            </div>

            <p className="text-gray-300 mb-6">
              Are you sure you want to delete "{deleteModal.event?.title}"? This action cannot be undone.
            </p>

            <div className="flex justify-end space-x-3">
              <button
                onClick={() => setDeleteModal({ isOpen: false, event: null })}
                className="px-4 py-2 text-gray-400 hover:text-white"
              >
                Cancel
              </button>
              <button
                onClick={confirmDelete}
                disabled={actionLoading}
                className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 disabled:opacity-50"
              >
                {actionLoading ? 'Deleting...' : 'Delete Event'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Bookings Modal */}
      {bookingsModal.isOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
          <div className="bg-gray-800 rounded-lg p-6 max-w-4xl w-full mx-4 max-h-[90vh] overflow-y-auto">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold text-white">Event Bookings & Payments</h3>
              <button
                onClick={() => setBookingsModal({ isOpen: false, event: null, bookings: [], loading: false })}
                className="text-gray-400 hover:text-white"
              >
                <X size={24} />
              </button>
            </div>

            {bookingsModal.event && (
              <div className="mb-6 p-4 bg-gray-700 rounded-lg">
                <h4 className="text-lg font-semibold text-white mb-2">{bookingsModal.event.title}</h4>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
                  <div>
                    <span className="text-gray-400">Date:</span>
                    <p className="text-white">{formatDate(bookingsModal.event.startDate)}</p>
                  </div>
                  <div>
                    <span className="text-gray-400">Venue:</span>
                    <p className="text-white">{bookingsModal.event.venue || 'TBD'}</p>
                  </div>
                  <div>
                    <span className="text-gray-400">Status:</span>
                    <p className="text-white">{bookingsModal.event.status}</p>
                  </div>
                  <div>
                    <span className="text-gray-400">Revenue:</span>
                    <p className="text-green-400">${(bookingsModal.event.revenue || 0).toLocaleString()}</p>
                  </div>
                </div>
              </div>
            )}

            {bookingsModal.loading ? (
              <div className="flex items-center justify-center py-8">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-red-500"></div>
                <span className="ml-3 text-gray-400">Loading bookings...</span>
              </div>
            ) : bookingsModal.bookings.length === 0 ? (
              <div className="text-center py-8">
                <FiUsers className="w-12 h-12 text-gray-500 mx-auto mb-4" />
                <p className="text-gray-400">No bookings found for this event</p>
              </div>
            ) : (
              <div className="space-y-6">
                {/* Summary Cards */}
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
                  <div className="bg-gradient-to-r from-blue-600 to-blue-700 p-4 rounded-lg text-center">
                    <div className="text-2xl font-bold text-white">{bookingsModal.bookings.length}</div>
                    <div className="text-blue-100 text-sm">Total Bookings</div>
                  </div>
                  <div className="bg-gradient-to-r from-green-600 to-green-700 p-4 rounded-lg text-center">
                    <div className="text-2xl font-bold text-white">
                      ${bookingsModal.bookings.reduce((sum, booking) => sum + booking.totalAmount, 0).toFixed(2)}
                    </div>
                    <div className="text-green-100 text-sm">Total Revenue</div>
                  </div>
                  <div className="bg-gradient-to-r from-purple-600 to-purple-700 p-4 rounded-lg text-center">
                    <div className="text-2xl font-bold text-white">
                      {bookingsModal.bookings.filter(b => b.status === 'confirmed').length}
                    </div>
                    <div className="text-purple-100 text-sm">Confirmed</div>
                  </div>
                  <div className="bg-gradient-to-r from-orange-600 to-orange-700 p-4 rounded-lg text-center">
                    <div className="text-2xl font-bold text-white">
                      {bookingsModal.bookings.reduce((sum, booking) => {
                        if (booking.ticketDetails && Array.isArray(booking.ticketDetails)) {
                          return sum + booking.ticketDetails.reduce((total, ticket) => total + ticket.quantity, 0);
                        }
                        return sum + 1;
                      }, 0)}
                    </div>
                    <div className="text-orange-100 text-sm">Total Tickets</div>
                  </div>
                </div>

                {/* Bookings List */}
                <div className="space-y-4">
                  <h5 className="text-lg font-semibold text-white mb-4 flex items-center">
                    <FiUsers className="mr-2" />
                    Customer Bookings
                  </h5>

                  {bookingsModal.bookings.map((booking, index) => (
                    <div key={booking._id || index} className="bg-gray-700 rounded-lg p-6 border border-gray-600 hover:border-gray-500 transition-colors">
                      <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between space-y-4 lg:space-y-0">

                        {/* Customer Info */}
                        <div className="flex-1">
                          <div className="flex items-start space-x-4">
                            <div className="w-12 h-12 bg-gray-600 rounded-full flex items-center justify-center">
                              <FiUser className="text-gray-300" size={20} />
                            </div>
                            <div className="flex-1">
                              <div className="flex items-center space-x-3 mb-2">
                                <h6 className="text-white font-semibold text-lg">
                                  {booking.user?.name || booking.userName || 'Unknown Customer'}
                                </h6>
                                <span className={`px-3 py-1 rounded-full text-xs font-medium ${
                                  booking.status === 'confirmed' 
                                    ? 'bg-green-900 text-green-300 border border-green-700' 
                                    : booking.status === 'pending'
                                    ? 'bg-yellow-900 text-yellow-300 border border-yellow-700'
                                    : 'bg-red-900 text-red-300 border border-red-700'
                                }`}>
                                  {booking.status.charAt(0).toUpperCase() + booking.status.slice(1)}
                                </span>
                              </div>

                              <div className="grid grid-cols-1 md:grid-cols-2 gap-x-6 gap-y-2 text-sm">
                                <div className="flex items-center text-gray-300">
                                  <span className="text-gray-400 w-20">Email:</span>
                                  <span>{booking.user?.email || booking.userEmail || 'N/A'}</span>
                                </div>
                                <div className="flex items-center text-gray-300">
                                  <span className="text-gray-400 w-20">Phone:</span>
                                  <span>{booking.user?.phone || 'N/A'}</span>
                                </div>
                                <div className="flex items-center text-gray-300">
                                  <span className="text-gray-400 w-20">Booking ID:</span>
                                  <span className="text-blue-400 font-mono">{booking.bookingId}</span>
                                </div>
                                <div className="flex items-center text-gray-300">
                                  <span className="text-gray-400 w-20">Date:</span>
                                  <span>{new Date(booking.bookingDate).toLocaleDateString()}</span>
                                </div>
                              </div>
                            </div>
                          </div>
                        </div>

                        {/* Booking Details */}
                        <div className="lg:ml-6 lg:w-80">
                          <div className="bg-gray-800 rounded-lg p-4 space-y-3">
                            <div className="flex justify-between items-center">
                              <span className="text-gray-400 text-sm">Tickets:</span>
                              <span className="text-white font-medium">
                                {booking.ticketDetails && Array.isArray(booking.ticketDetails) 
                                  ? booking.ticketDetails.reduce((total, ticket) => total + ticket.quantity, 0)
                                  : 1
                                } tickets
                              </span>
                            </div>

                            <div className="flex justify-between items-center">
                              <span className="text-gray-400 text-sm">Amount:</span>
                              <span className="text-green-400 font-bold text-lg">
                                ${booking.totalAmount.toFixed(2)} {(booking.currency || 'USD').toUpperCase()}
                              </span>
                            </div>

                            <div className="flex justify-between items-center">
                              <span className="text-gray-400 text-sm">Payment Method:</span>
                              <span className="text-white">
                                {booking.payment?.method || booking.paymentMethod || 'Card'}
                              </span>
                            </div>

                            <div className="flex justify-between items-center">
                              <span className="text-gray-400 text-sm">Transaction ID:</span>
                              <span className="text-blue-400 font-mono text-xs">
                                {booking.payment?.transactionId || booking.paymentIntentId || 'N/A'}
                              </span>
                            </div>
                          </div>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      )}

    </div>
  );
}

client/components/admin/AdminOverview.js.content:
import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { useNavigate } from "react-router-dom";
import toast from "react-hot-toast";
import { 
  FiUsers, 
  FiCalendar, 
  FiDollarSign, 
  FiTrendingUp,
  FiActivity,
  FiBarChart,
  FiClock,
  FiMapPin
} from "react-icons/fi";

export default function AdminOverview() {
  const navigate = useNavigate();
  const [stats, setStats] = useState({
    totalUsers: 0,
    totalEvents: 0,
    totalRevenue: 0,
    activeEvents: 0,
    totalAttendees: 0,
    monthlyGrowth: 0
  });
  const [recentActivities, setRecentActivities] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchOverviewData();
  }, []);

  const fetchOverviewData = async () => {
    try {
      const token = localStorage.getItem("adminToken");

      // Check if token exists
      if (!token) {
        toast.error("Admin authentication required");
        return;
      }

      const headers = {
        "Authorization": `Bearer ${token}`,
        "Content-Type": "application/json"
      };

      // Fetch overview data from admin API
      const overviewResponse = await fetch("/api/admin/overview", { headers });

      // Check for authentication errors
      if (overviewResponse.status === 401) {
        toast.error("Session expired. Please login again.");
        localStorage.removeItem("adminToken");
        localStorage.removeItem("adminUser");
        window.location.href = "/admin-login";
        return;
      }

      const overviewData = await overviewResponse.json();

      // Fetch recent activities
      const activitiesResponse = await fetch("/api/admin/activities", { headers });
      const activitiesData = await activitiesResponse.json();

      if (overviewResponse.ok) {
        setStats({
          totalUsers: overviewData.totalUsers,
          totalEvents: overviewData.totalEvents,
          totalRevenue: overviewData.totalRevenue,
          activeEvents: overviewData.activeEvents,
          totalAttendees: overviewData.totalAttendees,
          monthlyGrowth: overviewData.monthlyGrowth
        });
      }

      if (activitiesResponse.ok) {
        const formattedActivities = activitiesData.map(activity => ({
          id: activity.id,
          type: activity.type,
          message: activity.message,
          time: formatTimeAgo(activity.timestamp)
        }));
        setRecentActivities(formattedActivities);
      }

    } catch (error) {
      console.error("Error fetching overview data:", error);
    } finally {
      setLoading(false);
    }
  };

  const formatTimeAgo = (timestamp) => {
    const now = new Date();
    const time = new Date(timestamp);
    const diffMs = now - time;
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);

    if (diffMins < 60) {
      return `${diffMins} minutes ago`;
    } else if (diffHours < 24) {
      return `${diffHours} hours ago`;
    } else {
      return `${diffDays} days ago`;
    }
  };

  const statCards = [
    {
      title: "Total Users",
      value: stats.totalUsers,
      icon: FiUsers,
      color: "bg-blue-500",
      change: "+15.3%"
    },
    {
      title: "Total Events",
      value: stats.totalEvents,
      icon: FiCalendar,
      color: "bg-green-500",
      change: "+8.2%"
    },
    {
      title: "Total Revenue",
      value: `$${stats.totalRevenue.toLocaleString()}`,
      icon: FiDollarSign,
      color: "bg-purple-500",
      change: "+22.1%"
    },
    {
      title: "Active Events",
      value: stats.activeEvents,
      icon: FiActivity,
      color: "bg-orange-500",
      change: "+5.7%"
    },
    {
      title: "Total Attendees",
      value: stats.totalAttendees,
      icon: FiMapPin,
      color: "bg-red-500",
      change: "+18.9%"
    },
    {
      title: "Monthly Growth",
      value: `${stats.monthlyGrowth}%`,
      icon: FiTrendingUp,
      color: "bg-cyan-500",
      change: "+3.2%"
    }
  ];

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-red-500"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <h1 className="text-3xl font-bold text-white">Dashboard Overview</h1>
        <div className="flex items-center space-x-2 text-gray-400">
          <FiClock className="w-5 h-5" />
          <span>Last updated: {new Date().toLocaleString()}</span>
        </div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {statCards.map((card, index) => (
          <motion.div
            key={card.title}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: index * 0.1 }}
            className="bg-gray-800 rounded-xl p-6 border border-gray-700"
          >
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-400 text-sm font-medium">{card.title}</p>
                <p className="text-2xl font-bold text-white mt-1">{card.value}</p>
                <p className="text-green-400 text-sm mt-1">{card.change} from last month</p>
              </div>
              <div className={`${card.color} p-3 rounded-lg`}>
                <card.icon className="w-6 h-6 text-white" />
              </div>
            </div>
          </motion.div>
        ))}
      </div>

      {/* Charts and Activities */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Quick Stats Chart */}
        <motion.div
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.5 }}
          className="bg-gray-800 rounded-xl p-6 border border-gray-700"
        >
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-semibold text-white">Platform Performance</h3>
            <FiBarChart className="w-5 h-5 text-gray-400" />
          </div>
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <span className="text-gray-400">User Engagement</span>
              <div className="flex items-center space-x-2">
                <div className="w-32 bg-gray-700 rounded-full h-2">
                  <div className="bg-blue-500 h-2 rounded-full" style={{ width: "78%" }}></div>
                </div>
                <span className="text-white text-sm">78%</span>
              </div>
            </div>
            <div className="flex items-center justify-between">
              <span className="text-gray-400">Event Success Rate</span>
              <div className="flex items-center space-x-2">
                <div className="w-32 bg-gray-700 rounded-full h-2">
                  <div className="bg-green-500 h-2 rounded-full" style={{ width: "92%" }}></div>
                </div>
                <span className="text-white text-sm">92%</span>
              </div>
            </div>
            <div className="flex items-center justify-between">
              <span className="text-gray-400">Payment Success</span>
              <div className="flex items-center space-x-2">
                <div className="w-32 bg-gray-700 rounded-full h-2">
                  <div className="bg-purple-500 h-2 rounded-full" style={{ width: "96%" }}></div>
                </div>
                <span className="text-white text-sm">96%</span>
              </div>
            </div>
            <div className="flex items-center justify-between">
              <span className="text-gray-400">System Uptime</span>
              <div className="flex items-center space-x-2">
                <div className="w-32 bg-gray-700 rounded-full h-2">
                  <div className="bg-green-500 h-2 rounded-full" style={{ width: "99%" }}></div>
                </div>
                <span className="text-white text-sm">99%</span>
              </div>
            </div>
          </div>
        </motion.div>

        {/* Recent Activities */}
        <motion.div
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.5 }}
          className="bg-gray-800 rounded-xl p-6 border border-gray-700"
        >
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-semibold text-white">Recent Activities</h3>
            <FiActivity className="w-5 h-5 text-gray-400" />
          </div>
          <div className="space-y-3">
            {recentActivities.map((activity) => (
              <div key={activity.id} className="flex items-center space-x-3 p-3 bg-gray-700 rounded-lg">
                <div className={`w-2 h-2 rounded-full ${
                  activity.type === 'user' ? 'bg-blue-500' :
                  activity.type === 'event' ? 'bg-green-500' :
                  'bg-purple-500'
                }`}></div>
                <div className="flex-1">
                  <p className="text-white text-sm">{activity.message}</p>
                  <p className="text-gray-400 text-xs">{activity.time}</p>
                </div>
              </div>
            ))}
          </div>
        </motion.div>
      </div>

      {/* Quick Actions */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5, delay: 0.3 }}
        className="bg-gray-800 rounded-xl p-6 border border-gray-700"
      >
        <h3 className="text-lg font-semibold text-white mb-4">Quick Actions</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          <button 
            onClick={() => navigate('/admin/dashboard/users')}
            className="bg-blue-600 hover:bg-blue-700 text-white p-4 rounded-lg transition-colors transform hover:scale-105"
            title="Navigate to Users Management"
          >
            <FiUsers className="w-6 h-6 mb-2" />
            <span className="text-sm">Manage Users</span>
          </button>
          <button 
            onClick={() => navigate('/admin/dashboard/events')}
            className="bg-green-600 hover:bg-green-700 text-white p-4 rounded-lg transition-colors transform hover:scale-105"
            title="Navigate to Events Management"
          >
            <FiCalendar className="w-6 h-6 mb-2" />
            <span className="text-sm">View Events</span>
          </button>
          <button 
            onClick={() => navigate('/admin/dashboard/analytics')}
            className="bg-purple-600 hover:bg-purple-700 text-white p-4 rounded-lg transition-colors transform hover:scale-105"
            title="Navigate to Analytics"
          >
            <FiBarChart className="w-6 h-6 mb-2" />
            <span className="text-sm">Analytics</span>
          </button>
          <button 
            onClick={() => navigate('/admin/dashboard/settings')}
            className="bg-orange-600 hover:bg-orange-700 text-white p-4 rounded-lg transition-colors transform hover:scale-105"
            title="Navigate to Settings & Revenue"
          >
            <FiDollarSign className="w-6 h-6 mb-2" />
            <span className="text-sm">Revenue</span>
          </button>
        </div>
      </motion.div>
    </div>
  );
}

client/components/admin/AdminSettings.js.content:
import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { 
  FiSettings, 
  FiSave,
  FiMail,
  FiShield,
  FiGlobe,
  FiDollarSign,
  FiBell,
  FiDatabase,
  FiKey,
  FiToggleLeft,
  FiToggleRight
} from "react-icons/fi";
import toast from "react-hot-toast";

export default function AdminSettings() {
  const [settings, setSettings] = useState({
    general: {
      siteName: "Event Tribe",
      siteDescription: "Your premier event management platform",
      contactEmail: "admin@eventtribe.com",
      maxEventsPerUser: 10,
      defaultCurrency: "USD",
      timezone: "America/New_York"
    },
    security: {
      requireEmailVerification: true,
      requirePhoneVerification: false,
      enableTwoFactorAuth: true,
      passwordMinLength: 8,
      sessionTimeout: 30,
      maxLoginAttempts: 5
    },
    notifications: {
      emailNotifications: true,
      smsNotifications: false,
      pushNotifications: true,
      marketingEmails: false,
      systemAlerts: true,
      eventReminders: true
    },
    payments: {
      stripeEnabled: true,
      paypalEnabled: false,
      platformFee: 5.0,
      processingFee: 2.9,
      payoutSchedule: "weekly",
      minimumPayout: 50
    },
    api: {
      rateLimit: 1000,
      enableApiKeys: true,
      webhookUrl: "",
      apiVersion: "v1"
    }
  });
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState("general");

  const handleInputChange = (section, field, value) => {
    setSettings(prev => ({
      ...prev,
      [section]: {
        ...prev[section],
        [field]: value
      }
    }));
  };

  const handleToggle = (section, field) => {
    setSettings(prev => ({
      ...prev,
      [section]: {
        ...prev[section],
        [field]: !prev[section][field]
      }
    }));
  };

  const handleSave = async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem("adminToken");
      const response = await fetch("/api/admin/settings", {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`
        },
        body: JSON.stringify(settings)
      });

      if (response.ok) {
        toast.success("Settings updated successfully!");
      } else {
        toast.error("Failed to update settings");
      }
    } catch (error) {
      console.error("Error updating settings:", error);
      toast.error("Failed to update settings");
    } finally {
      setLoading(false);
    }
  };

  const settingsTabs = [
    { id: "general", label: "General", icon: FiSettings },
    { id: "security", label: "Security", icon: FiShield }
  ];

  const renderGeneralSettings = () => (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div>
          <label className="block text-sm font-medium text-gray-300 mb-2">
            Site Name
          </label>
          <input
            type="text"
            value={settings.general.siteName}
            onChange={(e) => handleInputChange("general", "siteName", e.target.value)}
            className="w-full bg-gray-700 text-white px-4 py-2 rounded-lg border border-gray-600 focus:border-red-500 focus:outline-none"
          />
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-300 mb-2">
            Contact Email
          </label>
          <input
            type="email"
            value={settings.general.contactEmail}
            onChange={(e) => handleInputChange("general", "contactEmail", e.target.value)}
            className="w-full bg-gray-700 text-white px-4 py-2 rounded-lg border border-gray-600 focus:border-red-500 focus:outline-none"
          />
        </div>
      </div>

      <div>
        <label className="block text-sm font-medium text-gray-300 mb-2">
          Site Description
        </label>
        <textarea
          value={settings.general.siteDescription}
          onChange={(e) => handleInputChange("general", "siteDescription", e.target.value)}
          rows={3}
          className="w-full bg-gray-700 text-white px-4 py-2 rounded-lg border border-gray-600 focus:border-red-500 focus:outline-none"
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div>
          <label className="block text-sm font-medium text-gray-300 mb-2">
            Max Events Per User
          </label>
          <input
            type="number"
            value={settings.general.maxEventsPerUser}
            onChange={(e) => handleInputChange("general", "maxEventsPerUser", parseInt(e.target.value))}
            className="w-full bg-gray-700 text-white px-4 py-2 rounded-lg border border-gray-600 focus:border-red-500 focus:outline-none"
          />
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-300 mb-2">
            Default Currency
          </label>
          <select
            value={settings.general.defaultCurrency}
            onChange={(e) => handleInputChange("general", "defaultCurrency", e.target.value)}
            className="w-full bg-gray-700 text-white px-4 py-2 rounded-lg border border-gray-600 focus:border-red-500 focus:outline-none"
          >
            <option value="USD">USD</option>
            <option value="EUR">EUR</option>
            <option value="GBP">GBP</option>
            <option value="JPY">JPY</option>
          </select>
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-300 mb-2">
            Timezone
          </label>
          <select
            value={settings.general.timezone}
            onChange={(e) => handleInputChange("general", "timezone", e.target.value)}
            className="w-full bg-gray-700 text-white px-4 py-2 rounded-lg border border-gray-600 focus:border-red-500 focus:outline-none"
          >
            <option value="America/New_York">Eastern Time</option>
            <option value="America/Chicago">Central Time</option>
