  FiUserCheck,
  FiUserX,
  FiDollarSign
} from "react-icons/fi";
import { X } from "lucide-react";
import toast from "react-hot-toast";

export default function AdminUsersManagement() {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [filterRole, setFilterRole] = useState("all");
  const [currentPage, setCurrentPage] = useState(1);
  const usersPerPage = 10;

  // Modal states
  const [viewModal, setViewModal] = useState({ isOpen: false, user: null });
  const [editModal, setEditModal] = useState({ isOpen: false, user: null });
  const [deleteModal, setDeleteModal] = useState({ isOpen: false, user: null });
  const [createModal, setCreateModal] = useState({ isOpen: false });

  const [actionLoading, setActionLoading] = useState(false);

  // Form states
  const [editForm, setEditForm] = useState({
    firstName: '',
    lastName: '',
    role: '',
    status: ''
  });
  const [createForm, setCreateForm] = useState({
    email: '',
    firstName: '',
    lastName: '',
    role: 'attendee',
    password: ''
  });

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    try {
      const { makeAdminApiCall } = await import("../../utils/adminAuth.js");
      const response = await makeAdminApiCall("/api/admin/users");

      if (!response) {
        return; // Auth error already handled
      }

      if (response.ok) {
        const data = await response.json();
        setUsers(data);
      } else {
        toast.error("Failed to fetch users");
      }
    } catch (error) {
      console.error("Error fetching users:", error);
      toast.error("Failed to fetch users");
    } finally {
      setLoading(false);
    }
  };

  // Action handlers
  const handleViewUser = async (user) => {
    try {
      const { makeAdminApiCall } = await import("../../utils/adminAuth.js");
      const userId = user._id || user.id;
      const response = await makeAdminApiCall(`/api/admin/users/${userId}`);

      if (!response) return; // Auth error handled

      if (response.ok) {
        const userData = await response.json();
        setViewModal({ isOpen: true, user: userData });
      } else {
        toast.error("Failed to fetch user details");
      }
    } catch (error) {
      console.error("Error fetching user details:", error);
      toast.error("Failed to fetch user details");
    }
  };

  const handleEditUser = async (user) => {
    try {
      const { makeAdminApiCall } = await import("../../utils/adminAuth.js");
      const userId = user._id || user.id;
      const response = await makeAdminApiCall(`/api/admin/users/${userId}`);

      if (!response) return; // Auth error handled

      if (response.ok) {
        const userData = await response.json();
        setEditForm({
          firstName: userData.firstName || '',
          lastName: userData.lastName || '',
          role: userData.role || 'attendee',
