        user.updatedAt ? new Date(user.updatedAt).toLocaleDateString() : 'N/A',
        user.firstName || 'N/A',
        user.lastName || 'N/A',
        user.suspended ? 'Suspended' : 'Active',
        (user.emailVerified && user.phoneVerified) ? 'Fully Verified' : 
        user.emailVerified ? 'Email Verified' : 
        user.phoneVerified ? 'Phone Verified' : 'Unverified'
      ]);

      // Combine headers and data
      const allRows = [csvHeaders, ...csvData];

      // Create CSV content
      const csvContent = allRows
        .map(row => row.map(field => {
          // Handle fields that might contain commas or quotes
          const stringField = String(field);
          if (stringField.includes(',') || stringField.includes('"') || stringField.includes('\n')) {
            return `"${stringField.replace(/"/g, '""')}"`;
          }
          return stringField;
        }).join(','))
        .join('\n');

      // Create and trigger download
      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");

      if (link.download !== undefined) {
        const url = URL.createObjectURL(blob);
        link.setAttribute("href", url);

        // Generate filename with current date
        const currentDate = new Date().toISOString().split('T')[0];
        link.setAttribute("download", `users-export-${currentDate}.csv`);

        link.style.visibility = 'hidden';
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);

        toast.success(`Users data exported successfully! (${filteredUsers.length} users)`);
      }
    } catch (error) {
      console.error("Export error:", error);
      toast.error("Failed to export users data");
    }
  };

  const handleRoleChange = async (user, newRole) => {
    try {
      const token = localStorage.getItem("adminToken");
      const response = await fetch(`/api/admin/users/${user.id}/role`, {
        method: 'PUT',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ role: newRole })
      });

      if (response.ok) {
        setUsers(users.map(u => 
          u.id === user.id ? { ...u, role: newRole } : u
        ));
        toast.success(`User role updated to ${newRole}`);
      } else {
        toast.error("Failed to update user role");
      }
    } catch (error) {
      console.error("Error updating user role:", error);
      toast.error("Failed to update user role");
    }
  };

  const filteredUsers = users.filter(user => {
    const matchesSearch = user.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         (user.firstName && user.firstName.toLowerCase().includes(searchTerm.toLowerCase())) ||
                         (user.lastName && user.lastName.toLowerCase().includes(searchTerm.toLowerCase()));
    const matchesRole = filterRole === "all" || user.role === filterRole;
    return matchesSearch && matchesRole;
