import { useState, useEffect } from "react";
import { 
  FiDollarSign, 
  FiTrendingUp, 
  FiCalendar, 
  FiUsers,
  FiRefreshCw,
  FiBarChart2,
  FiCreditCard
} from "react-icons/fi";
import toast from "react-hot-toast";
import { authService } from "../../services/authService.js";

export default function Earnings() {
  const [loading, setLoading] = useState(true);
  const [earnings, setEarnings] = useState(null);

  useEffect(() => {
    fetchEarnings();
  }, []);

  const fetchEarnings = async () => {
    try {
      setLoading(true);

      const response = await authService.apiRequest('/api/organizer/earnings');

      if (response.ok) {
        const earningsData = await response.json();
        setEarnings(earningsData);
        console.log('Earnings data fetched:', earningsData);
      } else {
        console.error('Failed to fetch earnings data:', response.status);
        toast.error("Failed to fetch earnings data");
      }
    } catch (error) {
      console.error("Error fetching earnings:", error);
      toast.error("Failed to fetch earnings data");
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-green-500"></div>
        <span className="ml-3 text-gray-400">Loading earnings data...</span>
